import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const _=JSON.parse('{"title":"扣子 / Coze 术语表","description":"对齐扣子、扣子编程、智能体、工作流、技能、插件、Studio、罗盘。写清不是什么，避免和豆包、Trae、官方 Claude Code 撞名。","frontmatter":{"title":"扣子 / Coze 术语表","description":"对齐扣子、扣子编程、智能体、工作流、技能、插件、Studio、罗盘。写清不是什么，避免和豆包、Trae、官方 Claude Code 撞名。","domain":"product","tags":["agent-builder"],"role":"glossary"},"headers":[],"relativePath":"zh/products/coze/coze-glossary.md","filePath":"zh/products/coze/coze-glossary.md","lastUpdated":1787110548000}'),n={name:"zh/products/coze/coze-glossary.md"};function s(d,e,l,p,c,i){return r(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="扣子-coze-术语表" tabindex="-1">扣子 / Coze 术语表 <a class="header-anchor" href="#扣子-coze-术语表" aria-label="Permalink to &quot;扣子 / Coze 术语表&quot;">​</a></h1><p>解释「是什么 / 不是什么」。操作在 <a href="./coze.html">教程</a> 和 <a href="./coze-cookbook.html">Cookbook</a>。参数在 <a href="./coze-cheatsheet.html">速查表</a>。</p><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    字节跳动 AI</span></span>
<span class="line"><span>          ┌────────────┼────────────┐</span></span>
<span class="line"><span>        豆包 #79      扣子家族        Trae #80</span></span>
<span class="line"><span>                         │            火山方舟 #82</span></span>
<span class="line"><span>        ┌────────────────┼────────────────┐</span></span>
<span class="line"><span>        │                │                │</span></span>
<span class="line"><span>     扣子工作台        扣子编程          扣子罗盘</span></span>
<span class="line"><span>   (coze.cn)        (code.coze.cn)     Prompt/评测/Trace</span></span>
<span class="line"><span>        │                │                │</span></span>
<span class="line"><span>   扣子/云端/本地      低代码 | AI编程      商业版</span></span>
<span class="line"><span>     Agent            智能体/工作流      Coze Loop 开源核</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                    Coze Studio 开源核</span></span></code></pre></div><p>订阅套餐是一层：个人 / 团队 / 企业决定积分和协作。搭建面在扣子编程。消费面在扣子。评测面在罗盘。</p><hr><h2 id="扣子" tabindex="-1">扣子 <a class="header-anchor" href="#扣子" aria-label="Permalink to &quot;扣子&quot;">​</a></h2><p><strong>是什么</strong>：官方定义是「面向 Agent 时代的新一代 AI 团队协作平台」（<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">what_is_coze</a>）。网页、macOS / Windows 桌面、移动端同步。</p><p><strong>不是什么</strong>：不是低代码画布，不是豆包，不是 Trae。对话里的 AI 编程只封装了网页 / App / 小程序 / 导入项目。</p><p><strong>为什么单独存在</strong>：人和多个 Agent 要共享项目、文件、日程、邮箱、云设备。这和「发布一个客服 Bot」不是同一件事。</p><hr><h2 id="扣子编程" tabindex="-1">扣子编程 <a class="header-anchor" href="#扣子编程" aria-label="Permalink to &quot;扣子编程&quot;">​</a></h2><p><strong>是什么</strong>：AI 驱动的应用开发平台，产出智能体、工作流、技能、网页、App、小程序（<a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">guides_welcome</a>）。入口 <code>code.coze.cn</code>。</p><p><strong>不是什么</strong>：不是 Trae，不能私有化（用 Studio）。低代码项目是它「较为早期的版本」，但低代码智能体今天仍从这里进。</p><hr><h2 id="低代码智能体" tabindex="-1">低代码智能体 <a class="header-anchor" href="#低代码智能体" aria-label="Permalink to &quot;低代码智能体&quot;">​</a></h2><p><strong>是什么</strong>：对话式 AI 项目。用户说话，模型按人设调用插件 / 工作流 / 知识库再回复。旧文档称 <strong>Bot</strong>。</p><p><strong>不是什么</strong>：不是全代码 AI 编程项目，也不是扣子工作台上用模板创建的「扣子 Agent」。</p><p><strong>典型场景</strong>：客服、虚拟伴侣、个人助理、外教（<a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>）。</p><hr><h2 id="全代码智能体" tabindex="-1">全代码智能体 <a class="header-anchor" href="#全代码智能体" aria-label="Permalink to &quot;全代码智能体&quot;">​</a></h2><p><strong>是什么</strong>：在扣子编程首页「智能体」选项卡里，用自然语言生成的可部署项目（<a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">guides_vibe_coding_agent</a>）。</p><p><strong>不是什么</strong>：不是拖拽编排页。部署形态偏 API 服务，和低代码「发到微信客服」不是同一条发布表。</p><hr><h2 id="工作流-对话流" tabindex="-1">工作流 / 对话流 <a class="header-anchor" href="#工作流-对话流" aria-label="Permalink to &quot;工作流 / 对话流&quot;">​</a></h2><p><strong>是什么</strong>：节点编排的可执行指令。工作流面向功能与数据；对话流面向 Chatbot（<a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">guides_workflow</a>）。</p><p><strong>不是什么</strong>：不是技能（技能不锁死路径）。不是插件（插件只是其中一个节点类型）。</p><hr><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p><strong>是什么</strong>：一组同域名 API 工具，用来扩模型边界（<a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">guides_plugin</a>）。</p><p><strong>不是什么</strong>：不是技能。技能还带「何时、如何用」的说明书。</p><hr><h2 id="技能-skill" tabindex="-1">技能 Skill <a class="header-anchor" href="#技能-skill" aria-label="Permalink to &quot;技能 Skill&quot;">​</a></h2><p><strong>是什么</strong>：<code>SKILL.md</code> + 可选 scripts / references / assets。智能体按需、渐进式加载（<a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">guides_skill_overview</a>）。</p><p><strong>不是什么</strong>：不是全程生效的系统提示词，不是固定工作流，不是 MCP 本身。</p><hr><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><p><strong>是什么</strong>：开发者维护的静态检索库，用来补事实、压幻觉。分扣子知识库和火山知识库。</p><p><strong>不是什么</strong>：不是记忆。记忆是用户侧动态数据，不能跨智能体。</p><hr><h2 id="扣子-agent-云端-agent-本地-agent" tabindex="-1">扣子 Agent / 云端 Agent / 本地 Agent <a class="header-anchor" href="#扣子-agent-云端-agent-本地-agent" aria-label="Permalink to &quot;扣子 Agent / 云端 Agent / 本地 Agent&quot;">​</a></h2><p>消费端（扣子）的三种运行位置（<a href="https://docs.coze.cn/cozespace_agent_overview" target="_blank" rel="noreferrer">cozespace_agent_overview</a>）：</p><table tabindex="0"><thead><tr><th>类型</th><th>跑在哪</th><th>适合</th></tr></thead><tbody><tr><td>扣子 Agent</td><td>扣子原生工作台</td><td>办公、创作、行业模板</td></tr><tr><td>云端 Agent</td><td>扣子云电脑</td><td>不想自己养环境的 Claude Code / Codex / OpenClaw / Hermes 框架</td></tr><tr><td>本地 Agent</td><td>你的电脑</td><td>要碰本机文件和工具链</td></tr></tbody></table><p>云端框架<strong>不是</strong> Anthropic / OpenAI 官方应用，不能登录对方账号，模型由扣子提供。</p><hr><h2 id="coze-cli" tabindex="-1">Coze CLI <a class="header-anchor" href="#coze-cli" aria-label="Permalink to &quot;Coze CLI&quot;">​</a></h2><p><strong>是什么</strong>：npm 包 <code>@coze/cli</code>，可执行文件 <code>coze</code>。把扣子编程的创建 / 开发 / 部署变成命令，给人和 Agent 用。</p><p><strong>不是什么</strong>：不是 Trae 的一部分，也不是扣子桌面端。Trae 只是官方举例的一个 Skill 安装目标。</p><hr><h2 id="扣子罗盘" tabindex="-1">扣子罗盘 <a class="header-anchor" href="#扣子罗盘" aria-label="Permalink to &quot;扣子罗盘&quot;">​</a></h2><p><strong>是什么</strong>：面向开发者的 Agent 开发运维平台：Prompt、评测、Trace（<a href="https://docs.coze.cn/cozeloop_what-is-cozeloop" target="_blank" rel="noreferrer">cozeloop_what-is-cozeloop</a>）。套餐逻辑与扣子编程相同。</p><p><strong>不是什么</strong>：不是搭建画布。开源对应物是 Coze Loop，商业版指标和企业治理更多。</p><hr><h2 id="coze-studio" tabindex="-1">Coze Studio <a class="header-anchor" href="#coze-studio" aria-label="Permalink to &quot;Coze Studio&quot;">​</a></h2><p><strong>是什么</strong>：开源「一站式 AI agent development tool」，Apache-2.0。官方 README：可视化创建、调试、部署智能体 / 应用 / 工作流。</p><p><strong>不是什么</strong>：不是扣子编程商业版。Studio 是单机核，不含工作空间、企业组织、多人协作（<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">guides_FAQ</a>）。</p><hr><h2 id="coze-pro-企业版" tabindex="-1">Coze Pro / 企业版 <a class="header-anchor" href="#coze-pro-企业版" aria-label="Permalink to &quot;Coze Pro / 企业版&quot;">​</a></h2><p><strong>是什么</strong>：火山引擎产品页 <a href="https://www.volcengine.com/product/coze-pro" target="_blank" rel="noreferrer">coze-pro</a> 与文档里的企业套餐（标准 / 旗舰）。混合计费：包年包月 + 按量。</p><p><strong>不是什么</strong>：不是一个和扣子编程并列的第三套画布。权益、SSO、VPC 以 <a href="https://docs.coze.cn/guides_edition" target="_blank" rel="noreferrer">guides_edition</a> 为准。</p><hr><h2 id="豆包-trae-火山方舟" tabindex="-1">豆包 / Trae / 火山方舟 <a class="header-anchor" href="#豆包-trae-火山方舟" aria-label="Permalink to &quot;豆包 / Trae / 火山方舟&quot;">​</a></h2><p><strong>是什么</strong>：同厂其它 AI 产品。豆包是聊天。Trae 是 IDE。方舟是模型 API。</p><p><strong>不是什么</strong>：不是本目录该展开的搭建教程。低代码智能体曾经能发到豆包渠道，该入口已下线。不要把「在人设里选了豆包模型」说成「这就是豆包产品」。</p><hr><h2 id="已下线或改名" tabindex="-1">已下线或改名 <a class="header-anchor" href="#已下线或改名" aria-label="Permalink to &quot;已下线或改名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说法</th><th>现状</th></tr></thead><tbody><tr><td>Bot</td><td>现称低代码智能体</td></tr><tr><td>发布到豆包</td><td>2026-07-01 下线入口</td></tr><tr><td>抖音分身</td><td>2025-09-03 下架</td></tr><tr><td>工作流 / 图像流商店</td><td>已下架</td></tr><tr><td>扣子编程私有化</td><td>官方：暂不支持，改 Studio</td></tr><tr><td>商店里复制别人完整配置</td><td>商店为私有配置；抄结构用模板商店</td></tr></tbody></table>`,67)])])}const z=a(n,[["render",s]]);export{_ as __pageData,z as default};
